head.script:
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 숨기기
        txb_BndMktactTpCd.hide();
        grd_ExcelList.hide();
        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_Top);
        // 호출파라미터설정
        scwin.setParam();
        // 목록조회
        scwin.search();

        // 엑셀데이터셋 초기화
        const sbmOptions = {
            id : "sbm_dts_ExcelList",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_ExcelList=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        if (txb_BndMktactTpCd.getValue() === "320") {
            let ColID = new Object();
            ColID.BND_APPL_ID = grd_List.getColumnID(2);
            $c.cm.setColumnProp(grd_List, ColID.BND_APPL_ID, "Show", false);
            $c.cm.setColumnProp(grd_List, "ISU_ISUR_NM", "Width", "290");
        }
        if (txb_BndMktactTpCd.getValue() === "201" || txb_BndMktactTpCd.getValue() === "202") {
            let ColID = new Object();
            ColID.STD_ISUR_CD = grd_List.getColumnID(3);
            ColID.ISU_ISUR_NM = grd_List.getColumnID(4);
            $c.cm.setColumnProp(grd_List, ColID.STD_ISUR_CD, "name", '발행기관코드');
            $c.cm.setColumnProp(grd_List, ColID.ISU_ISUR_NM, "name", '회사명');
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90005.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90005.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_ApprovFileCreat_onclick
 * @description 「결재파일생성」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ApprovFileCreat_onclick = async function() {
    try {
        await scwin.searchApprovFileDtl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90005.btn_ApprovFileCreat_onclick" });
    }
};

/**
 * @method
 * @name grd_List_onheadcheckclick
 * @description grd_List onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_onheadcheckclick = function(col, colid, bCheck) {
    try {
        $c.bns.fn_SetAllCheckBox(grd_List, dts_List, bCheck);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90005.grd_List_onheadcheckclick" });
    }
};

/**
 * @method
 * @name dts_ExcelList_OnLoadCompleted
 * @description dts_ExcelList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ExcelList_OnLoadCompleted = async function(rowcount) {
    try {
        if (rowcount > 0) {
            let fileContn = '';
            for (let i = 1; i <= dts_ExcelList.getRowCount(); i++) {
                fileContn = dts_ExcelList.getCellData(i, 'APPROV_FILE_CONTN');
                if (fileContn === '') {
                    await $c.win.alert('[' + i + '행] 결제파일데이타가 없습니다.');
                    return;
                }
            }
            let mktactCd = txb_BndMktactTpCd.getValue();
            const title = dts_ExcelList.getCellData(1, 'TITLE');
            const fileNm = title;
            $c.cm.setColumnProp(grd_ExcelList, 'APPROV_FILE_CONTN', 'Name', title);
            grd_ExcelList.ExportFileEx($c.ut.cGetToday('yyyymmdd') + '_' + fileNm, true, 1, false);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90005.dts_ExcelList_OnLoadCompleted" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchApprovFileDtl
 * @description 결재파일 내역을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchApprovFileDtl = async function() {
    // 선택체크
    if (dts_List.getRowCount() === 0) return;
    if (!$c.bns.fn_IsChecked(dts_List, '')) {
        await $c.win.alert("대상을 선택하십시오.");
        return;
    }

    // 조회설정
    let qryId = '';
    let dsNm = 'BNS_APPROV_FILE_WRT';
    let mktactCd = txb_BndMktactTpCd.getValue();

    // 파라미터설정
    let param = '';
    let applId = '';
    let stdCd = '';
    let strtDd = '';
    if (mktactCd !== '320') {
        param += "&{P}V_BND_APPL_ID=" + scwin.getApplId();
        applId = scwin.getApplId();
    } else {
        param += "&{P}V_STD_CD=" + scwin.getApplIdPack().STD_ISUR_CD;
        param += "&{P}V_STRT_DD=" + scwin.getApplIdPack().STRT_DD;
        stdCd = scwin.getApplIdPack().STD_ISUR_CD;
        strtDd = scwin.getApplIdPack().STRT_DD;
    }

    // 국채,지방채
    if (mktactCd === '111' || mktactCd === '121' || mktactCd === '112' || mktactCd === '122') {
        qryId = 'lds.stf.bnsnew.select.listApprovFileDtl111121112122';
    }
    // WIT종목지정
    else if (mktactCd === '113') {
        qryId = 'lds.stf.bnsnew.select.listApprovFileDtl113';
    }
    // WIT종목정보확정
    else if (mktactCd === '330') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt330';
    }
    // 특수채,회사채,외국채
    else if (mktactCd === '131' || mktactCd === '132' || mktactCd === '141' || mktactCd === '151') {
        qryId = 'lds.stf.bnsnew.select.listApprovFileDtl131132141151';
    }
    // 상호 변경, 합병/회사분할, 종목분할
    else if (mktactCd === '201' || mktactCd === '202' || mktactCd === '203') {
        qryId = 'lds.stf.bnschg.select.listApprovFileDt201202203';
    }
    // BW행사(최초)
    else if (mktactCd === '205') {
        qryId = 'lds.stf.bnschg.select.listApprovFileDt205';
    }
    // 월별 금액조정,  중도상환(부분/전액), 권리행사(일반사채)
    else if (mktactCd === '301' || mktactCd === '303' || mktactCd === '304' || mktactCd === '315') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt301303304315';
    }
    // 일별 금액조정
    else if (mktactCd === '320') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt320';
    }

    // 권리행사(주식관련사채권)
    else if (mktactCd === '302') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt302';
    }
    // 추가상장
    else if (mktactCd === '305') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt305';
    }
    // 권리행사가액 변경
    else if (mktactCd === '306') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt306';
    }
    // 발행가액, 표면이자율 변경
    else if (mktactCd === '307' || mktactCd === '308') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt307308';
    }
    // FRN 변동금리, 상환일 변경
    else if (mktactCd === '309' || mktactCd === '311') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt309311';
    }
    /**
     * 보증기관 변경 (폐지, ASIS 테이블 - TB_BB212, TOBE 테이블 - 無)
     * mktactCd == '312' || mktactCd == '318' || mktactCd == '319'
     */

    // 신용평가등급 변경
    else if (mktactCd === '313') {
        return '신용평가기관 채권정기-수시 평정 내역';
    }
    // 수동상장폐지
    else if (mktactCd === '314') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt314';
    }
    // 기타 2023-07-04 추가.
    else if (mktactCd === '316') {
        qryId = 'lds.stf.bnsisuchg.select.listApprovFileDt316';
    }
    // 스트립
    else if (mktactCd === '401') {
        qryId = 'lds.stf.bnschg.select.listApprovFileDt401Prnp';
        $c.bns.fn_SearchBns("ULDBNS90005.xml", dts_Prnp, dsNm, qryId, param);
        if (dts_Prnp.getRowCount() === 0) {
            await $c.win.alert('결재파일데이타가 없습니다.');
            return;
        }
        let url = "/bns/BnsApprovFileDownload.do?";
        url += "BND_MKTACT_TP_CD=" + mktactCd;
        url += "&BND_APPL_ID=" + scwin.getApplId();
        location.href = url;
        return;
    }
    // 스트립추가재결합
    else if (mktactCd === '402') {
        // 원금
        qryId = 'lds.stf.bnschg.select.listApprovFileDt402Prnp';
        $c.bns.fn_SearchBns("ULDBNS90005.xml", dts_Prnp, dsNm, qryId, param);
        if (dts_Prnp.getRowCount() === 0) {
            await $c.win.alert('결재파일데이타가 없습니다.');
            return;
        }
        let url = "/bns/BnsApprovFileDownload.do?";
        url += "BND_MKTACT_TP_CD=" + mktactCd;
        url += "&BND_APPL_ID=" + scwin.getApplId();
        location.href = url;
        return;
    }

    // 스트립이 아닐 경우 웹브라우에서 보일 수 있도록 자바를 통해 다운로드 되도록 호출.
    // 문제 있을 시 주석처리.
    let url = "/bns/BnsApprovFileDownload.do?";
    url += "BND_MKTACT_TP_CD=" + mktactCd;
    url += "&BND_APPL_ID=" + applId;
    url += "&STD_CD=" + stdCd;
    url += "&STRT_DD=" + strtDd;
    url += "&QUERY_ID=" + qryId;
    location.href = url;
    return;

    // 스트립이 아닐 경우 결재데이터 조회
    $c.bns.fn_SearchBns("ULDBNS90005.xml", dts_ExcelList, dsNm, qryId, param);
};

/**
 * @method
 * @name getApplId
 * @description 결재파일내역 신청ID를 리턴한다.
 * @returns {void}
 * @hidden N
 */
scwin.getApplId = function() {
    let chk = '';
    let applId = '';
    let returnVal = '';
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        applId = dts_List.getCellData(i, 'BND_APPL_ID');
        if (applId === '') continue;
        chk = dts_List.getCellData(i, "CHECKED");
        if (chk === "T" || chk === "1") {
            returnVal += "'" + applId + "',";
        }
    }
    return returnVal.substring(0, returnVal.length - 1);
};

/**
 * @method
 * @name getApplIdPack
 * @description 일별금액조정 결재파일내역 표준코드, 적용일을 리턴한다.
 * @returns {void}
 * @hidden N
 */
scwin.getApplIdPack = function() {
    let chk = '';
    let stdcd = '',
        strtdd = '';
    let returnValStdCd = '',
        returnValStrtDd = '';
    const objReturnVal = new Object();
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        chk = dts_List.getCellData(i, "CHECKED");
        if (chk === "T" || chk === "1") {
            stdcd = dts_List.getCellData(i, 'STD_ISUR_CD');
            strtdd = dts_List.getCellData(i, 'STRT_DD');
            returnValStdCd += "'" + stdcd + "',";
            returnValStrtDd += "'" + strtdd + "',";
        }
    }
    objReturnVal.STD_ISUR_CD = returnValStdCd.substring(0, returnValStdCd.length - 1);
    objReturnVal.STRT_DD = returnValStrtDd.substring(0, returnValStrtDd.length - 1);
    return objReturnVal;
};

/**
 * @method
 * @name search
 * @description 결재파일새성정보를 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    // setObjectValue(txb_BndMktactTpCd, '401');
    let param = '';
    param += "&{P}V_BND_MKTACT_TP_CD=" + txb_BndMktactTpCd.getValue();
    let dsNm = 'BNS_APPROV_FILE_WRT';
    let qryId = 'lds.stf.bnscommon.select.listApprovFileWrt';
    $c.bns.fn_SearchBns("ULDBNS90005.xml", dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        const arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        txb_BndMktactTpCd.setValue(arrPar[0].BND_MKTACT_TP_CD);
    }
};

/**
 * @method
 * @name grd_List_CanColumnPosChange
 * @description grd List Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
